return ['domain'=>'wirecore-disable-rest','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'de_DE','project-id-version'=>'WireCore Disable REST 1.0.0','pot-creation-date'=>'2026-10-14T04:40:50+00:00','po-revision-date'=>'2026-10-14 00:00+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['Disables the WordPress REST API selectively – globally, per namespace or per route, including routes of other plugins.'=>'Sperrt die WordPress REST API gezielt – global, pro Namespace oder pro Route, auch für Routen anderer Plugins.','Settings'=>'Einstellungen','Read'=>'Lesen','Write'=>'Schreiben','automatic'=>'automatisch','(no namespace)'=>'(ohne Namespace)','IPs allowed'=>'IP frei','Users allowed'=>'Benutzer frei','Roles allowed'=>'Rollen frei','IPs denied'=>'IP gesperrt','Roles denied'=>'Rollen gesperrt','Allowed'=>'Freigaben','Denied'=>'Sperren','Expand all'=>'Alle aufklappen','Collapse all'=>'Alle zuklappen','The routes could not be loaded via the REST API:'=>'Die Routen konnten nicht über die REST API geladen werden:','WooCommerce Store API (cart, checkout)'=>'WooCommerce Store API (Warenkorb, Kasse)','oEmbed (embedding posts on other sites)'=>'oEmbed (Einbetten von Beiträgen auf anderen Seiten)','LiteSpeed Cache (QUIC.cloud)'=>'LiteSpeed Cache (QUIC.cloud)','Insufficient permissions.'=>'Keine Berechtigung.','Routes'=>'Routen','Log'=>'Log','Tools'=>'Werkzeuge','Settings saved.'=>'Die Einstellungen wurden gespeichert.','Saved. Invalid IP entries were discarded.'=>'Gespeichert. Ungültige IP-Angaben wurden verworfen.','The rules could not be read. JavaScript is required to save them.'=>'Die Regeln konnten nicht gelesen werden. Zum Speichern wird JavaScript benötigt.','The log has been cleared.'=>'Das Log wurde geleert.','Settings imported.'=>'Die Einstellungen wurden importiert.','Import failed. Please choose an export file of this plugin.'=>'Der Import ist fehlgeschlagen. Bitte eine Exportdatei dieses Plugins wählen.','WIRECORE_DR_OFF is set in wp-config.php: no rules are enforced.'=>'WIRECORE_DR_OFF ist in der wp-config.php gesetzt: Es werden keine Regeln durchgesetzt.','Default rule'=>'Standardregel','Applies to all routes without a custom rule. “Read” covers GET/HEAD, “Write” covers POST/PUT/PATCH/DELETE. The most specific rule wins: route before namespace before automatic allowance before default.'=>'Gilt für alle Routen ohne eigene Regel. „Lesen“ umfasst GET/HEAD, „Schreiben“ POST/PUT/PATCH/DELETE. Die spezifischste Regel gewinnt: Route vor Namespace vor automatischer Freigabe vor Standard.','Quick actions'=>'Schnellaktionen','Block everything for guests'=>'Alles für Gäste sperren','Block everything'=>'Alles sperren','User list (/wp/v2/users) for admins only'=>'Benutzerliste (/wp/v2/users) nur für Admins','Reset custom rules'=>'Eigene Regeln zurücksetzen','Changes take effect only after saving.'=>'Änderungen werden erst beim Speichern übernommen.','Use “Advanced” to additionally allow or deny IP addresses, roles and users for a namespace or route. The entries of a namespace apply to all of its routes.'=>'Über „Erweitert“ lassen sich für einen Namespace oder eine Route zusätzlich IP-Adressen, Rollen und Benutzer freigeben oder sperren. Die Einträge eines Namespace gelten für alle seine Routen.','Loading routes …'=>'Routen werden geladen …','Save rules'=>'Regeln speichern','Advanced:'=>'Erweitert:','Applies to reading and writing. Denials take precedence over allowances and also apply to administrators. Allowances grant access regardless of the rule. For a route, the entries of its namespace apply as well.'=>'Gilt für Lesen und Schreiben. Sperren gehen vor Freigaben und gelten auch für Administratoren. Freigaben öffnen den Zugriff unabhängig von der Regel. Bei einer Route gelten zusätzlich die Einträge ihres Namespace.','Allow'=>'Freigeben','IP addresses / CIDR ranges'=>'IP-Adressen / CIDR-Bereiche','User IDs'=>'Benutzer-IDs','Roles'=>'Rollen','Deny'=>'Sperren','Apply'=>'Übernehmen','Cancel'=>'Abbrechen','Changes are saved with “Save rules”.'=>'Gespeichert wird mit „Regeln speichern“.','Advanced'=>'Erweitert','%1$d routes registered in %2$d namespaces, %3$d of them reachable for logged-out visitors (without whitelists).'=>'%1$d Routen in %2$d Namespaces registriert, davon %3$d für nicht angemeldete Besucher erreichbar (ohne Whitelists).','Search route or namespace …'=>'Route oder Namespace suchen …','Source'=>'Quelle','All sources'=>'Alle Quellen','Status'=>'Status','All routes'=>'Alle Routen','With custom rule'=>'Mit eigener Regel','Reachable for guests'=>'Für Gäste erreichbar','Blocked for guests'=>'Für Gäste gesperrt','%d route'=>'%d Route' . "\0" . '%d Routen','Automatically allowed'=>'Automatisch freigegeben','Route'=>'Route','Methods'=>'Methoden','Effective'=>'Effektiv','Rules without a registered route'=>'Nicht gefundene Regeln','Rules for namespaces or routes that are currently not registered, e.g. because a plugin is deactivated. They are kept until they are set to “Inherit” and nothing is entered under “Advanced”.'=>'Regeln für Namespaces oder Routen, die gerade nicht registriert sind, z. B. weil ein Plugin deaktiviert ist. Sie bleiben erhalten, bis sie auf „Erben“ stehen und unter „Erweitert“ nichts mehr eingetragen ist.','Namespace / route'=>'Namespace / Route','Administrators'=>'Administratoren','Never block administrators (recommended – the block editor needs the REST API)'=>'Administratoren nie sperren (empfohlen – der Block-Editor benötigt die REST API)','HTTPS'=>'HTTPS','Allow the REST API over HTTPS only'=>'REST API nur über HTTPS erlauben','JSONP'=>'JSONP','Disable JSONP responses (?_jsonp=)'=>'JSONP-Antworten (?_jsonp=) deaktivieren','REST links'=>'REST-Links','Remove REST links from HTTP headers, HTML head and RSD'=>'REST-Links aus HTTP-Header, HTML-Head und RSD entfernen','Index'=>'Index','Hide blocked routes and namespaces in the index (/wp-json/)'=>'Gesperrte Routen und Namespaces im Index (/wp-json/) ausblenden','Access'=>'Zugriff','Roles for “Logged-in only”'=>'Rollen für „Nur angemeldet“','No selection = all logged-in users.'=>'Keine Auswahl = alle angemeldeten Nutzer.','Allowed user IDs'=>'Freigegebene Benutzer-IDs','These users are never blocked. One ID per line.'=>'Diese Benutzer werden nie gesperrt. Eine ID pro Zeile.','Allowed IP addresses'=>'Freigegebene IP-Adressen','Applies to all routes. One IP or CIDR range per line, e.g. 203.0.113.5 or 10.0.0.0/8. Allowances for individual routes are available in the route list under “Advanced”. Your current IP: %s'=>'Gilt für alle Routen. Eine IP oder ein CIDR-Bereich pro Zeile, z. B. 203.0.113.5 oder 10.0.0.0/8. Freigaben für einzelne Routen gibt es in der Routenliste unter „Erweitert“. Deine aktuelle IP: %s','Blocked IP addresses'=>'Gesperrte IP-Adressen','These IPs get no access to any route – not even as administrator or through an allowance. One IP or CIDR range per line.'=>'Diese IPs erhalten für alle Routen keinen Zugriff – auch nicht als Administrator oder über eine Freigabe. Eine IP oder ein CIDR-Bereich pro Zeile.','Automatic allowances'=>'Automatische Freigaben','These plugins need the REST API for visitors on the front end (forms, cart, statistics). Their namespaces are public as long as no custom rule is set for the namespace or the route in the route list. The setting has no effect for plugins that are not installed.'=>'Diese Plugins brauchen die REST API für Besucher im Frontend (Formulare, Warenkorb, Statistik). Ihre Namespaces sind öffentlich, solange in der Routenliste keine eigene Regel für den Namespace oder die Route gesetzt ist. Für nicht installierte Plugins hat die Einstellung keine Wirkung.','Error response'=>'Fehlerantwort','Error message'=>'Fehlermeldung','Access to the REST API is restricted.'=>'Der Zugriff auf die REST API ist eingeschränkt.','Status code'=>'Statuscode','401 – Unauthorized'=>'401 – Nicht authentifiziert','403 – Forbidden'=>'403 – Verboten','404 – Not found (route appears not to exist)'=>'404 – Nicht gefunden (Route wirkt nicht vorhanden)','Hardening'=>'Härtung','Logging'=>'Protokoll','Log blocked requests (last %d)'=>'Blockierte Requests protokollieren (letzte %d)','IP address in log'=>'IP-Adresse im Log','Store in full'=>'Vollständig speichern','Store shortened (e.g. 203.0.113.0)'=>'Gekürzt speichern (z. B. 203.0.113.0)','Do not store'=>'Nicht speichern','Applies to new entries. Existing entries remain unchanged until the log is cleared.'=>'Gilt für neue Einträge. Bereits gespeicherte Einträge bleiben unverändert, bis das Log geleert wird.','No HTTPS'=>'Kein HTTPS','Deny list'=>'Sperrliste','The log is disabled. It can be enabled under “Settings”.'=>'Das Log ist deaktiviert. Es lässt sich unter „Einstellungen“ einschalten.','Blocked requests in total: %d'=>'Blockierte Requests insgesamt: %d','Time'=>'Zeit','Method'=>'Methode','IP'=>'IP','User ID'=>'Benutzer-ID','Rule'=>'Regel','No entries.'=>'Keine Einträge.','Clear log'=>'Log leeren','Self-test'=>'Selbsttest','Calls the REST API without authentication and shows what logged-out visitors see.'=>'Ruft die REST API ohne Anmeldung auf und zeigt, was nicht angemeldete Besucher sehen.','Run test'=>'Test starten','URL'=>'URL','Response'=>'Antwort','Export'=>'Export','Export settings'=>'Einstellungen exportieren','Import'=>'Import','Replaces all current settings with those from the file.'=>'Ersetzt alle aktuellen Einstellungen durch die der Datei.','Import settings'=>'Einstellungen importieren','Emergency switch'=>'Notausschalter','If a rule locks you out of the admin area, this line in wp-config.php disables all rules:'=>'Sperrt eine Regel den Zugang zum Admin-Bereich aus, setzt diese Zeile in der wp-config.php alle Regeln außer Kraft:','For developers'=>'Für Entwickler','<code>wirecore_dr_error</code> – filters the WP_Error of a blocked request (parameters: error, route pattern, method). If the filter returns <code>true</code>, the request is allowed after all.'=>'<code>wirecore_dr_error</code> – Filter für den WP_Error einer gesperrten Anfrage (